        return { item: item, s: unitScore(item) };
      }).sort(function (a, b) {
        return (b.s.primary - a.s.primary) || (b.s.idfSum - a.s.idfSum) ||
          (a.s.gi - b.s.gi) || (a.s.ui - b.s.ui);
      });
