      /^help( me)?$/,
      /\bhow do i use (this|dogear|the app)\b/,
      /\bwhat can i ask( you)?\b/,
      /\bhow do i (get started|start)\b/,
    ]],
  ];

  function match(text) {
    var t = norm(text);
    if (!t) return null;
    for (var i = 0; i < TOPICS.length; i++) {
      var pats = TOPICS[i][1];
      for (var j = 0; j < pats.length; j++) {
        if (pats[j].test(t)) return TOPICS[i][0];
      }
