      if (!id || warmModelId === id || voice.engineReady()) return;
      warmModelId = id;
      var warm = function () {
        if (!voice) return;
        voice.warmEngine().then(function (r) {
          if (!r || !r.ok) warmModelId = null;
        });
      };
