      out.push('## Exchange ' + (i + 1));
      out.push('');
      out.push('_' + convAnchorLine(e) + '_');
      out.push('');
      out.push('**You:** ' + e.q);
      out.push('');
      out.push('**DogEar:** ' + e.a);
      out.push('');
    });
