      parts.push('<p class="anchor">' + escHtml(convAnchorLine(e)) + '</p>');
      parts.push('<p><span class="you">You:</span> ' + escHtml(e.q) + '</p>');
      parts.push('<p><strong>DogEar:</strong> ' + escHtml(e.a) + '</p>');
