    c = c.replace(/^(what|who|whom|whose|when|where|why|how|which)\s+/i, '');
    c = c.replace(/^(is|are|was|were|does|do|did|can|could|should|would)\s+/i, '');
    c = c.replace(/^the\s+/i, '');
