        onVoicesChanged: function () { refreshVoicePicker(); },
      };
      if (usePack) {
        // Reader-core 0.4.0 seam: the pack transport drives the
        // reader; its synthetic localService voices pass the
        // reader's on-device filter unchanged, and the default
