      if (unlocked()) return true;
      if (continuing) return true;
      if (hasStarted(docId)) return true;
      return !atCap();
    }

    function snapshot() {
      var st = load();
      return {
        day: st.day,
        freeMinutes: freeMinutes,
        usedMinutes: usedMinutes(),
        remainingMinutes: remainingMinutes(),
        unlocked: !!unlocked(),
        docs: st.docs,
