      STORAGE_KEY: STORAGE_KEY,
      LEGACY_STORAGE_KEY: LEGACY_STORAGE_KEY,
      begin: begin,
      observe: observe,
      complete: complete,
      usedMinutes: usedMinutes,
      remainingMinutes: remainingMinutes,
      hasStarted: hasStarted,
      atCap: atCap,
      canStart: canStart,
      snapshot: snapshot,
      minutesForText: function (text) { return minutesForText(text, wpm); },
