              meta.totalParas += c.paraCount;
            });
            return setMeta(d.id, meta).then(function () {
              if (getTextSync(d.id) === docParagraphs(legacy).join('\n\n')) {
                try { localStorage.removeItem(bodyKey(d.id)); } catch (e) {}
