          rangeMsgScope = { selection: true };
          setRangeMsg('Reading only the part you selected.');
          if (current.reader.getState() === 'playing') {
            armWatchdog(current.reader);
          }
        }
      });
    }
    wireBrain();
    wireConv();
    wireNotes();
